import React from 'react';
import { questions } from '../data/questions';
import SocialMeta from './SocialMeta';

const Summary = ({ answers, onRestart }) => {
  // Calculate total cost
  const totalCost = Object.values(answers).reduce((sum, answer) => sum + (answer?.cost || 0), 0);

  // Group answers by tags
  const tagGroups = Object.values(answers).reduce((groups, answer) => {
    if (answer?.tags) {
      answer.tags.forEach(tag => {
        if (!groups[tag]) groups[tag] = [];
        groups[tag].push(answer);
      });
    }
    return groups;
  }, {});

  // Get dominant style
  const getDominantStyle = () => {
    const styleCounts = {
      traditional: tagGroups.traditional?.length || 0,
      modern: tagGroups.modern?.length || 0,
      minimal: tagGroups.minimal?.length || 0,
      luxury: tagGroups.luxury?.length || 0,
    };
    return Object.entries(styleCounts).reduce((a, b) => a[1] > b[1] ? a : b)[0];
  };

  const dominantStyle = getDominantStyle();

  const getStyleName = (style) => {
    switch(style) {
      case 'traditional': return 'แบบดั้งเดิม';
      case 'modern': return 'แบบสมัยใหม่';
      case 'minimal': return 'แบบเรียบง่าย';
      case 'luxury': return 'แบบหรูหรา';
      default: return '';
    }
  };

  // Calculate break-even points for different donation amounts
  const breakEvenPoints = {
    '500': Math.ceil(totalCost / 500),
    '1000': Math.ceil(totalCost / 1000),
    '2000': Math.ceil(totalCost / 2000)
  };

  // Get key decisions for the funeral description
  const getFuneralDescription = () => {
    const style = getStyleName(dominantStyle);
    const venue = answers[3]?.text || 'ไม่ระบุ';
    const duration = answers[2]?.text || 'ไม่ระบุ';
    const atmosphere = answers[8]?.text || 'ไม่ระบุ';
    const music = answers[9]?.text || 'ไม่ระบุ';
    const activities = answers[10]?.text || 'ไม่ระบุ';
    const remembrance = answers[4]?.text || 'ไม่ระบุ';

    return {
      style,
      venue,
      duration,
      atmosphere,
      music,
      activities,
      remembrance
    };
  };

  const funeral = getFuneralDescription();

  const handleShare = () => {
    if (navigator.share) {
      navigator.share({
        title: 'แผนงานศพของฉัน',
        text: `สไตล์: ${funeral.style}\nงบประมาณ: ${totalCost.toLocaleString()} บาท\nจุดคุ้มทุน: ${breakEvenPoints['500']} คน (500 บาท/คน)`,
        url: window.location.href
      });
    }
  };

  return (
    <>
      <SocialMeta funeral={funeral} totalCost={totalCost} />
      <div className="min-h-screen bg-gradient-to-b from-gray-900 to-black text-white p-6 animate-fade-in">
        <div className="max-w-4xl mx-auto space-y-8">
          {/* Header with Instagram-worthy design */}
          <div className="text-center space-y-4 animate-slide-up">
            <div className="relative">
              <h1 className="text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-red-500 to-pink-500">
                สรุปแผนงานศพของคุณ
              </h1>
              <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-32 h-1 bg-gradient-to-r from-red-500 to-pink-500 rounded-full"></div>
            </div>
            <p className="text-2xl text-gray-300 mt-4">สไตล์ {funeral.style}</p>
          </div>

          {/* Funeral Overview Card */}
          <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 shadow-xl animate-slide-up" style={{ animationDelay: '0.2s' }}>
            <h2 className="text-3xl font-bold text-red-400 mb-6">ภาพรวมงานศพ</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-4">
                <div>
                  <h3 className="text-lg font-semibold text-gray-300">สถานที่</h3>
                  <p className="text-white">{funeral.venue}</p>
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-300">ระยะเวลา</h3>
                  <p className="text-white">{funeral.duration}</p>
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-300">บรรยากาศ</h3>
                  <p className="text-white">{funeral.atmosphere}</p>
                </div>
              </div>
              <div className="space-y-4">
                <div>
                  <h3 className="text-lg font-semibold text-gray-300">ดนตรี</h3>
                  <p className="text-white">{funeral.music}</p>
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-300">กิจกรรม</h3>
                  <p className="text-white">{funeral.activities}</p>
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-300">ความทรงจำ</h3>
                  <p className="text-white">{funeral.remembrance}</p>
                </div>
              </div>
            </div>
          </div>

          {/* Cost Analysis */}
          <div className="bg-gray-800/50 backdrop-blur-sm rounded-2xl p-8 shadow-xl animate-slide-up" style={{ animationDelay: '0.4s' }}>
            <h2 className="text-3xl font-bold text-red-400 mb-6">การวิเคราะห์ค่าใช้จ่าย</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="text-center p-6 bg-gray-700/50 rounded-xl">
                <h3 className="text-xl font-semibold text-gray-300 mb-2">งบประมาณรวม</h3>
                <p className="text-4xl font-bold text-white">{totalCost.toLocaleString()} บาท</p>
              </div>
              <div className="text-center p-6 bg-gray-700/50 rounded-xl">
                <h3 className="text-xl font-semibold text-gray-300 mb-2">จุดคุ้มทุน</h3>
                <div className="space-y-2">
                  <p className="text-lg text-white">{breakEvenPoints['500']} คน (500 บาท/คน)</p>
                  <p className="text-lg text-white">{breakEvenPoints['1000']} คน (1,000 บาท/คน)</p>
                  <p className="text-lg text-white">{breakEvenPoints['2000']} คน (2,000 บาท/คน)</p>
                </div>
              </div>
            </div>
          </div>

          {/* Style Highlights */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 animate-slide-up" style={{ animationDelay: '0.6s' }}>
            {Object.entries(tagGroups).map(([tag, items]) => (
              <div key={tag} className="bg-gray-800/50 backdrop-blur-sm rounded-xl p-6 shadow-xl">
                <h3 className="text-xl font-semibold mb-4 text-red-400">
                  {getStyleName(tag)}
                </h3>
                <ul className="space-y-2">
                  {items.slice(0, 3).map((item, index) => (
                    <li key={index} className="text-gray-300">
                      {typeof item.text === 'string' ? item.text : ''}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>

          {/* Action Buttons */}
          <div className="flex justify-center space-x-4 animate-fade-in-delay">
            <button
              onClick={onRestart}
              className="px-8 py-3 bg-red-600 text-white rounded-xl hover:bg-red-700 transition-colors duration-300"
            >
              เริ่มต้นใหม่
            </button>
            <button
              onClick={handleShare}
              className="px-8 py-3 bg-gray-700 text-white rounded-xl hover:bg-gray-600 transition-colors duration-300"
            >
              แชร์ผลลัพธ์
            </button>
          </div>

          {/* Footer with Quote */}
          <div className="text-center space-y-4 animate-fade-in-delay">
            <div className="relative">
              <p className="text-2xl italic text-gray-300">
                "การวางแผนงานศพคือการแสดงความรักครั้งสุดท้าย"
              </p>
              <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 w-16 h-0.5 bg-red-500 rounded-full"></div>
            </div>
            <p className="text-sm text-gray-500">#วางแผนงานศพ #เตรียมตัวก่อนตาย</p>
          </div>
        </div>
      </div>
    </>
  );
};

export default Summary;
